#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define HASH_BITS 20
#define HASH_SIZE (1 << HASH_BITS)
#define HASH_MASK (HASH_SIZE - 1)

typedef struct {
    uint64_t key;
    uint32_t gen;
    int32_t best_act; // -1: decline, -2: approve, 0: bureau, 1: income, 2: bank
    double val;
} HashEntry;

static HashEntry table[HASH_SIZE];
static uint32_t current_gen = 1;
static double P_mat[3][6][6];
static const double payoffs[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};
static double check_cost = 20.0;

static inline uint64_t hash64(uint64_t x) {
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    x = x ^ (x >> 31);
    return x;
}

// Insert item (1..18) into sorted 8-byte key (each byte holds 0..18)
static inline uint64_t insert_sorted(uint64_t key, int item) {
    uint8_t bytes[8];
    memcpy(bytes, &key, 8);
    // Find first 0 or insert position in sorted order
    int pos = 0;
    while (pos < 8 && bytes[pos] != 0 && bytes[pos] <= item) {
        pos++;
    }
    for (int j = 7; j > pos; j--) {
        bytes[j] = bytes[j - 1];
    }
    bytes[pos] = (uint8_t)item;
    uint64_t res;
    memcpy(&res, bytes, 8);
    return res;
}

static double solve_rec(uint64_t key, const double w[6], int rem, int *out_act) {
    double stop_approve = 0.0;
    for (int s = 0; s < 6; s++) {
        stop_approve += w[s] * payoffs[s];
    }
    double stop_val = (stop_approve > 0.0) ? stop_approve : 0.0;
    int stop_act = (stop_approve > 0.0) ? -2 : -1;

    if (rem == 0) {
        if (out_act) *out_act = stop_act;
        return stop_val;
    }

    double Z = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
    double perf_info = w[0] * payoffs[0] + w[1] * payoffs[1];
    if (perf_info - check_cost * Z <= stop_val + 1e-12) {
        if (out_act) *out_act = stop_act;
        return stop_val;
    }

    uint64_t h = hash64(key) & HASH_MASK;
    while (table[h].gen == current_gen) {
        if (table[h].key == key) {
            if (out_act) *out_act = table[h].best_act;
            return table[h].val;
        }
        h = (h + 1) & HASH_MASK;
    }

    double best_val = stop_val;
    int best_act = stop_act;

    const int k_order[3] = {2, 1, 0};
    for (int ki = 0; ki < 3; ki++) {
        int k = k_order[ki];
        double ub_k = perf_info - check_cost * Z;
        if (ub_k <= best_val + 1e-12) continue;

        double q_val = -check_cost * Z;
        int possible = 1;
        for (int b = 5; b >= 0; b--) {
            double w_next[6];
            for (int s = 0; s < 6; s++) {
                w_next[s] = w[s] * P_mat[k][s][b];
            }
            double ub_b = w_next[0] * payoffs[0] + w_next[1] * payoffs[1];
            uint64_t next_key = insert_sorted(key, k * 6 + b + 1);
            double v_next = solve_rec(next_key, w_next, rem - 1, NULL);
            q_val += v_next;
            ub_k -= (ub_b - v_next);
            if (ub_k <= best_val + 1e-12) {
                possible = 0;
                break;
            }
        }
        if (possible && q_val > best_val + 1e-12) {
            best_val = q_val;
            best_act = k;
        }
    }

    // Re-probe to insert (since recursive calls may have inserted into table)
    h = hash64(key) & HASH_MASK;
    while (table[h].gen == current_gen && table[h].key != key) {
        h = (h + 1) & HASH_MASK;
    }
    table[h].key = key;
    table[h].gen = current_gen;
    table[h].best_act = best_act;
    table[h].val = best_val;

    if (out_act) *out_act = best_act;
    return best_val;
}

double solve_applicant(const double prior[6], const double P_in[108], int max_checks, double cost, int *out_act, double q_vals[5]) {
    current_gen++;
    if (current_gen == 0) {
        memset(table, 0, sizeof(table));
        current_gen = 1;
    }
    memcpy(P_mat, P_in, sizeof(double) * 108);
    check_cost = cost;

    double stop_approve = 0.0;
    for (int s = 0; s < 6; s++) stop_approve += prior[s] * payoffs[s];
    q_vals[0] = 0.0; // decline
    q_vals[1] = stop_approve; // approve

    double Z = prior[0] + prior[1] + prior[2] + prior[3] + prior[4] + prior[5];
    for (int k = 0; k < 3; k++) {
        if (max_checks <= 0) {
            q_vals[2 + k] = -1e9;
            continue;
        }
        double q = -check_cost * Z;
        for (int b = 5; b >= 0; b--) {
            double w_next[6];
            for (int s = 0; s < 6; s++) w_next[s] = prior[s] * P_mat[k][s][b];
            uint64_t next_key = insert_sorted(0ULL, k * 6 + b + 1);
            q += solve_rec(next_key, w_next, max_checks - 1, NULL);
        }
        q_vals[2 + k] = q;
    }

    double best_val = q_vals[0];
    int best_act = -1;
    if (q_vals[1] > best_val + 1e-12) {
        best_val = q_vals[1];
        best_act = -2;
    }
    for (int k = 0; k < 3; k++) {
        if (q_vals[2 + k] > best_val + 1e-12) {
            best_val = q_vals[2 + k];
            best_act = k;
        }
    }
    if (out_act) *out_act = best_act;
    return best_val;
}

