static double eval_rec(uint64_t key, const double w_est[6], const double w_true[6], int rem) {
    int act;
    solve_rec(key, w_est, rem, &act);
    if (act == -1) {
        return 0.0;
    } else if (act == -2) {
        double val = 0.0;
        for (int s = 0; s < 6; s++) val += w_true[s] * payoffs[s];
        return val;
    } else {
        int k = act;
        double Z_true = 0.0;
        for (int s = 0; s < 6; s++) Z_true += w_true[s];
        double total = -check_cost * Z_true;
        for (int b = 5; b >= 0; b--) {
