    uint64_t h = hash64(0ULL) & HASH_MASK;
    int root_act = -1;
    while (table[h].gen == current_gen) {
        if (table[h].key == 0ULL) {
            root_act = table[h].best_act;
            break;
        }
        h = (h + 1) & HASH_MASK;
    }
    if (root_act == -1) return 0.0;
    if (root_act == -2) {
        double val = 0.0;
        for (int s = 0; s < 6; s++) val += prior[s] * payoffs[s];
        return val;
    }
    int k = root_act;
    double Z_true = 0.0;
    for (int s = 0; s < 6; s++) Z_true += prior[s];
    double total = -check_cost * Z_true;
    for (int b = 5; b >= 0; b--) {
        double we_next[6], wt_next[6];
        for (int s = 0; s < 6; s++) {
            we_next[s] = prior[s] * P_mat[k][s][b];
            wt_next[s] = prior[s] * P_true_mat[k][s][b];
        }
        uint64_t next_key = insert_sorted(0ULL, k * 6 + b + 1);
        total += eval_rec(next_key, we_next, wt_next, max_checks - 1);
    }
    return total;
}

